Here's an example C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

int main() {
    // Define the word to search for
    std::string search_word = "example";

    // Define the file name and path
    std::string file_name = "example.txt";

    // Open the file for reading
    std::ifstream file(file_name);

    // Check if the file opened successfully
    if (!file) {
        std::cerr << "Error opening file: " << file_name << std::endl;
        return 1;
    }

    // Create a map to store the word counts
    std::unordered_map<std::string, int> word_counts;

    // Read the file line by line
    std::string line;
    while (std::getline(file, line)) {
        // Split the line into words
        std::istringstream iss(line);
        std::string word;
        while (iss >> word) {
            // Convert the word to lowercase for case-insensitive matching
            std::transform(word.begin(), word.end(), word.begin(), ::tolower);

            // Increment the word count if the word matches the search word
            if (word == search_word) {
                word_counts[search_word]++;
            }
        }
    }

    // Close the file
    file.close();

    // Print the word count
    if (word_counts.find(search_word) != word_counts.end()) {
        std::cout << "The word \"" << search_word << "\" appears " << word_counts[search_word] << " times in " << file_name << std::endl;
    } else {
        std::cout << "The word \"" << search_word << "\" does not appear in " << file_name << std::endl;
    }

    return 0;
}
```

